package orgclient

// client_test.go — tests for NewClient/Close, the dial/transport-posture
// core that used to be byte-identical across all 13 services/*-bff/internal/
// orgclient copies. Prevents a regression where the unified constructor
// silently falls back to plaintext on a partial mTLS config, or fails to
// wire one of the union's sub-clients.

import (
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
)

// TestNewClient_Insecure exercises the constructor + Close on the insecure
// (no MTLS_*_FILE) transport posture. grpc.NewClient is lazy, so no live
// org-svc is needed — the dial only resolves credentials and a target.
func TestNewClient_Insecure(t *testing.T) {
	client, err := NewClient("passthrough:///org-svc:50051", mtls.Config{})
	require.NoError(t, err)
	require.NotNil(t, client)
	require.NotNil(t, client.featureFlag, "featureFlag stub must be wired")
	require.NotNil(t, client.tenant, "tenant stub must be wired")
	require.NotNil(t, client.shareCode, "shareCode stub must be wired")
	require.Equal(t, mtls.ModeInsecure, client.Mode)
	require.NoError(t, client.Close())
}

// TestNewClient_PartialMTLS_Errors proves NewClient rejects a partial mTLS
// config (fail closed) rather than silently falling back to insecure.
func TestNewClient_PartialMTLS_Errors(t *testing.T) {
	_, err := NewClient("passthrough:///org-svc:50051", mtls.Config{
		CertFile: "/tmp/does-not-matter.pem",
	})
	require.Error(t, err)
}


