package orgclient

import (
	"context"
	"net"
	"testing"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/grpcclient"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	feature_flagv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/feature_flag/v1"
)

// fakeBlockingFeatureFlagServer never returns from ListFeatureFlags — it
// blocks until the RPC's context is done, so a client-side deadline is the
// only thing that can end the call. This proves grpcclient.DialOptions'
// deadline interceptor is actually wired into NewClient (Task 5, gRPC
// deadlines): without it, a caller context with no deadline of its own
// (like context.Background()) would hang here forever.
type fakeBlockingFeatureFlagServer struct {
	feature_flagv1.UnimplementedFeatureFlagServiceServer
}

func (f *fakeBlockingFeatureFlagServer) ListFeatureFlags(
	ctx context.Context,
	_ *feature_flagv1.ListFeatureFlagsRequest,
) (*feature_flagv1.ListFeatureFlagsResponse, error) {
	<-ctx.Done()
	return nil, ctx.Err()
}

// TestNewClient_AppliesDeadline_WhenCallerSetsNone dials a real (loopback)
// org-svc double whose ListFeatureFlags handler never returns on its own,
// then calls it with context.Background() (no deadline). Before this
// package wired grpcclient.DialOptions(TierFast, ...) into NewClient's
// grpc.NewClient call, this call had no default deadline and would hang
// indefinitely. OMNICORE_TIMEOUT_SCALE=0.01 is set process-wide in this
// package's TestMain (zz_p0_05_insecure_testmain_test.go), so the scaled
// TierFast deadline (~50ms) fires almost immediately, keeping the test fast
// while still exercising the real production dial path end to end.
func TestNewClient_AppliesDeadline_WhenCallerSetsNone(t *testing.T) {
	lis, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("net.Listen: %v", err)
	}
	srv := grpc.NewServer()
	feature_flagv1.RegisterFeatureFlagServiceServer(srv, &fakeBlockingFeatureFlagServer{})
	go func() { _ = srv.Serve(lis) }()
	t.Cleanup(srv.Stop)

	client, err := NewClient(lis.Addr().String(), mtls.Config{})
	if err != nil {
		t.Fatalf("NewClient() error = %v; want nil", err)
	}
	t.Cleanup(func() { _ = client.Close() })

	start := time.Now()
	done := make(chan error, 1)
	go func() {
		_, callErr := client.ListFeatureFlags(context.Background())
		done <- callErr
	}()

	select {
	case callErr := <-done:
		if callErr == nil {
			t.Fatal("ListFeatureFlags() error = nil; want a deadline error from the never-responding server")
		}
		if elapsed := time.Since(start); elapsed > 3*time.Second {
			t.Errorf("ListFeatureFlags() took %v; want it bounded by the scaled TierFast deadline (~50ms)", elapsed)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("ListFeatureFlags() did not return within 5s — no default deadline is applied to a caller " +
			"context with none set (grpcclient.DialOptions not wired into NewClient?)")
	}
}

// TestNewClient_HonorsCallerTierOverride covers the other half of the
// deadline contract: a caller that narrows the per-call budget with
// grpcclient.WithTier must have THAT deadline applied, not NewClient's
// TierFast default. Without the interceptor wired, neither deadline exists
// and the call hangs on a peer that accepts the connection but never speaks
// gRPC.
//
// The listener here deliberately accepts and then goes silent, rather than
// serving a real grpc.Server as the test above does: that keeps the RPC
// pending in the transport with no server-side handler involved at all, so
// the only thing that can end it is a client-side deadline.
func TestNewClient_HonorsCallerTierOverride(t *testing.T) {
	lis, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("net.Listen: %v", err)
	}
	t.Cleanup(func() { _ = lis.Close() })
	go func() {
		for {
			conn, acceptErr := lis.Accept()
			if acceptErr != nil {
				return
			}
			// Accepted, but never written to and never closed.
			t.Cleanup(func() { _ = conn.Close() })
		}
	}()

	client, err := NewClient(lis.Addr().String(), mtls.Config{})
	if err != nil {
		t.Fatalf("NewClient() error = %v; want nil", err)
	}
	t.Cleanup(func() { _ = client.Close() })

	ctx := grpcclient.WithTier(context.Background(), 50*time.Millisecond)
	done := make(chan error, 1)
	go func() {
		_, callErr := client.ListFeatureFlags(ctx)
		done <- callErr
	}()

	select {
	case callErr := <-done:
		if callErr == nil {
			t.Fatal("ListFeatureFlags() error = nil; want DeadlineExceeded from the silent peer")
		}
		st, ok := status.FromError(callErr)
		if !ok {
			t.Fatalf("ListFeatureFlags() error = %v; want a gRPC status error", callErr)
		}
		if st.Code() != codes.DeadlineExceeded {
			t.Errorf("ListFeatureFlags() code = %v; want %v", st.Code(), codes.DeadlineExceeded)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("ListFeatureFlags() did not return within 2s — the caller's WithTier deadline " +
			"was not applied (grpcclient.DialOptions not wired into NewClient?)")
	}
}


