package orgclient

// featureflag_test.go — tests for ListFeatureFlags, the RPC every consuming
// BFF uses to build its featureflags.Cache. Prevents a regression where the
// key->enabled mapping drops flags, mishandles the empty-response case, or
// swallows an upstream gRPC error instead of propagating it to the cache's
// fail-open fetcher.

import (
	"context"
	"net"
	"testing"

	"github.com/stretchr/testify/require"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/status"
	"google.golang.org/grpc/test/bufconn"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	feature_flagv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/feature_flag/v1"
)

// fakeFeatureFlagServer is a bufconn-backed FeatureFlagServiceServer replaying
// a canned flag set.
type fakeFeatureFlagServer struct {
	feature_flagv1.UnimplementedFeatureFlagServiceServer

	resp *feature_flagv1.ListFeatureFlagsResponse
	err  error
}

func (f *fakeFeatureFlagServer) ListFeatureFlags(_ context.Context, _ *feature_flagv1.ListFeatureFlagsRequest) (*feature_flagv1.ListFeatureFlagsResponse, error) {
	if f.err != nil {
		return nil, f.err
	}
	return f.resp, nil
}

// newFeatureFlagTestClient stands up an in-memory org-svc gRPC server backed
// by fake and returns an orgclient.Client wired to it over bufconn.
func newFeatureFlagTestClient(t *testing.T, fake feature_flagv1.FeatureFlagServiceServer) *Client {
	t.Helper()

	lis := bufconn.Listen(1024 * 1024)
	srv := grpc.NewServer()
	feature_flagv1.RegisterFeatureFlagServiceServer(srv, fake)

	go func() { _ = srv.Serve(lis) }()
	t.Cleanup(srv.Stop)

	conn, err := grpc.NewClient(
		"passthrough:///bufnet",
		grpc.WithContextDialer(func(ctx context.Context, _ string) (net.Conn, error) {
			return lis.DialContext(ctx)
		}),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = conn.Close() })

	return &Client{
		conn:        conn,
		featureFlag: feature_flagv1.NewFeatureFlagServiceClient(conn),
		Mode:        mtls.ModeInsecure,
	}
}

func TestListFeatureFlags_ReturnsMappedFlags(t *testing.T) {
	fake := &fakeFeatureFlagServer{
		resp: &feature_flagv1.ListFeatureFlagsResponse{
			Flags: []*feature_flagv1.FeatureFlag{
				{Key: "range", Enabled: true},
				{Key: "dialogue", Enabled: false},
			},
		},
	}
	client := newFeatureFlagTestClient(t, fake)

	flags, err := client.ListFeatureFlags(context.Background())
	require.NoError(t, err)
	require.Equal(t, map[string]bool{"range": true, "dialogue": false}, flags)
}

func TestListFeatureFlags_EmptyResponse(t *testing.T) {
	fake := &fakeFeatureFlagServer{resp: &feature_flagv1.ListFeatureFlagsResponse{}}
	client := newFeatureFlagTestClient(t, fake)

	flags, err := client.ListFeatureFlags(context.Background())
	require.NoError(t, err)
	require.Empty(t, flags)
}

func TestListFeatureFlags_PropagatesRPCError(t *testing.T) {
	fake := &fakeFeatureFlagServer{err: status.Error(codes.Unavailable, "org-svc down")}
	client := newFeatureFlagTestClient(t, fake)

	flags, err := client.ListFeatureFlags(context.Background())
	require.Error(t, err)
	require.Nil(t, flags)
	require.Equal(t, codes.Unavailable, status.Code(err))
}


