package orgclient

// membership_test.go — tests for VerifyMembership and ListMembershipsByTenant,
// the two TenantServiceClient wrappers used by BFFs that need the caller's
// org-membership role (ResolveOrgRole middleware) or a tenant's roster
// (share-picker). Prevents a regression where either wrapper drops fields on
// the way in/out, or swallows an upstream gRPC error.

import (
	"context"
	"net"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/status"
	"google.golang.org/grpc/test/bufconn"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
)

// fakeTenantServer is a bufconn-backed TenantServiceServer that records the
// last VerifyMembership/ListMembershipsByTenant request it received and
// replays a canned response.
type fakeTenantServer struct {
	tenantv1.UnimplementedTenantServiceServer

	gotVerifyMembership *tenantv1.VerifyMembershipRequest
	verifyResp          *tenantv1.VerifyMembershipResponse
	verifyErr           error
	// verifyDeadline captures the context deadline (server-side) observed
	// on the last VerifyMembership call, zero if none was set.
	verifyDeadline time.Time

	gotListMembershipsByTenant *tenantv1.ListMembershipsByTenantRequest
	listResp                   *tenantv1.ListMembershipsByTenantResponse
	listErr                    error
	// listDeadline captures the context deadline (server-side) observed on
	// the last ListMembershipsByTenant call, zero if none was set.
	listDeadline time.Time
}

func (f *fakeTenantServer) VerifyMembership(ctx context.Context, req *tenantv1.VerifyMembershipRequest) (*tenantv1.VerifyMembershipResponse, error) {
	f.gotVerifyMembership = req
	if dl, ok := ctx.Deadline(); ok {
		f.verifyDeadline = dl
	}
	if f.verifyErr != nil {
		return nil, f.verifyErr
	}
	return f.verifyResp, nil
}

func (f *fakeTenantServer) ListMembershipsByTenant(ctx context.Context, req *tenantv1.ListMembershipsByTenantRequest) (*tenantv1.ListMembershipsByTenantResponse, error) {
	f.gotListMembershipsByTenant = req
	if dl, ok := ctx.Deadline(); ok {
		f.listDeadline = dl
	}
	if f.listErr != nil {
		return nil, f.listErr
	}
	return f.listResp, nil
}

// newTenantTestClient stands up an in-memory org-svc gRPC server backed by
// fake and returns an orgclient.Client wired to it over bufconn.
func newTenantTestClient(t *testing.T, fake tenantv1.TenantServiceServer) *Client {
	t.Helper()

	lis := bufconn.Listen(1024 * 1024)
	srv := grpc.NewServer()
	tenantv1.RegisterTenantServiceServer(srv, fake)

	go func() { _ = srv.Serve(lis) }()
	t.Cleanup(srv.Stop)

	conn, err := grpc.NewClient(
		"passthrough:///bufnet",
		grpc.WithContextDialer(func(ctx context.Context, _ string) (net.Conn, error) {
			return lis.DialContext(ctx)
		}),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = conn.Close() })

	return &Client{
		conn:   conn,
		tenant: tenantv1.NewTenantServiceClient(conn),
		Mode:   mtls.ModeInsecure,
	}
}

func TestVerifyMembership_ForwardsFields_AndUnwrapsRole(t *testing.T) {
	fake := &fakeTenantServer{
		verifyResp: &tenantv1.VerifyMembershipResponse{IsMember: true, MembershipRole: "OWNER"},
	}
	client := newTenantTestClient(t, fake)

	const userID, orgID = "user-1", "org-1"
	isMember, role, err := client.VerifyMembership(context.Background(), userID, orgID)
	require.NoError(t, err)
	require.True(t, isMember)
	require.Equal(t, "OWNER", role)

	got := fake.gotVerifyMembership
	require.NotNil(t, got, "VerifyMembership should have been invoked on the server")
	require.Equal(t, userID, got.GetUserId())
	require.Equal(t, orgID, got.GetOrgId())
}

func TestVerifyMembership_NonMember_ReturnsEmptyRole(t *testing.T) {
	fake := &fakeTenantServer{verifyResp: &tenantv1.VerifyMembershipResponse{IsMember: false}}
	client := newTenantTestClient(t, fake)

	isMember, role, err := client.VerifyMembership(context.Background(), "user-x", "org-y")
	require.NoError(t, err)
	require.False(t, isMember)
	require.Empty(t, role)
}

func TestVerifyMembership_PropagatesRPCError(t *testing.T) {
	fake := &fakeTenantServer{verifyErr: status.Error(codes.Unavailable, "org-svc down")}
	client := newTenantTestClient(t, fake)

	isMember, role, err := client.VerifyMembership(context.Background(), "user-x", "org-y")
	require.Error(t, err)
	require.False(t, isMember)
	require.Empty(t, role)
	require.Equal(t, codes.Unavailable, status.Code(err))
}

func TestListMembershipsByTenant_ForwardsTenantID_AndUnwrapsMemberships(t *testing.T) {
	fake := &fakeTenantServer{
		listResp: &tenantv1.ListMembershipsByTenantResponse{
			Memberships: []*tenantv1.Membership{
				{Id: "m-1", TenantId: "org-1", UserId: "user-1", Role: tenantv1.MembershipRole_MEMBERSHIP_ROLE_MEMBER},
				{Id: "m-2", TenantId: "org-1", UserId: "user-2", Role: tenantv1.MembershipRole_MEMBERSHIP_ROLE_ADMIN},
			},
		},
	}
	client := newTenantTestClient(t, fake)

