import (
	"context"
	"time"

	sharecodev1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/share_code/v1"
)

// RedeemCode resolves a pasted share code (ORG or USER kind) to the set of
// members it enrolls (enroll-by-code redesign, #332; range-bff only). org-svc's
// RedeemCode is azp-gated to {shell-bff, range-bff}; the inbound ctx carries
// the caller's forwarded bearer token in outgoing gRPC metadata — the
// forwarded token carries azp=shell-bff since the browser authenticates via
// shell-bff's Keycloak public client (same azp subtlety as VerifyMembership).
// Performs a BYPASSRLS cross-org lookup on org-svc's side and returns a
// oneof: ORG → the minting org id/name + ALL its current members; USER → the
// single user's id/display_name/home_org_id. Returns INVALID_ARGUMENT for an
// unknown code, FAILED_PRECONDITION for a revoked one — both propagated
// untranslated for the handler to map. Bounded with a short deadline so a
// stalled org-svc cannot pin the request goroutine.
func (c *Client) RedeemCode(ctx context.Context, code string) (*sharecodev1.RedeemCodeResponse, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	return c.shareCode.RedeemCode(ctx, &sharecodev1.RedeemCodeRequest{Code: code})
}


