package orgclient

// P0-05: this package's tests dial/serve with an intentionally empty
// mtls.Config to exercise the pre-Vault-PKI insecure fallback, not real
// certs. mtls.EnforceMode now fails that path by default, so opt in to the
// explicit dev/CI escape hatch for the duration of this package's test run.
