// silently failing after mtls.EnforceMode's default posture changes.

import (
	"os"
	"testing"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/grpcclient"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
)

func TestMain(m *testing.M) {
	os.Setenv(mtls.AllowInsecureEnvVar, "true")
	// Task 5 (gRPC deadlines): set OMNICORE_TIMEOUT_SCALE here, in TestMain,
	// rather than via t.Setenv inside an individual test. grpcclient caches
	// this value behind a process-wide sync.Once on its FIRST read — which
	// happens the first time any test in this binary makes an RPC through a
	// client dialed with grpcclient.DialOptions. TestMain runs before every
	// test, so this guarantees the scaled-down value wins the cache
	// regardless of which test (or file) happens to trigger that first read.
	os.Setenv(grpcclient.TimeoutScaleEnvVar, "0.01")
	os.Exit(m.Run())
