package orgclient

import (
	"context"

	feature_flagv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/feature_flag/v1"
)

// ListFeatureFlags returns the effective enabled state for every known
// vertical key from org-svc. The feature-flag table is platform-global (no
// RLS), so no tenant GUC is required for this read-only call. The returned
// flags are keyed by vertical name ("dialogue", "range", "studio", ...);
// absent keys are default-on per org-svc semantics (and per
// featureflags.Cache's own fail-open contract). The inbound ctx MUST carry
// the caller's bearer token in outgoing gRPC metadata (forwarded by the
// featureflags middleware / RequireVerticalEnabled) — org-svc rejects
// unauthenticated calls.
func (c *Client) ListFeatureFlags(ctx context.Context) (map[string]bool, error) {
	resp, err := c.featureFlag.ListFeatureFlags(ctx, &feature_flagv1.ListFeatureFlagsRequest{})
	if err != nil {
		return nil, err
	}
	flags := make(map[string]bool, len(resp.GetFlags()))
	for _, f := range resp.GetFlags() {
		flags[f.GetKey()] = f.GetEnabled()
	}
	return flags, nil
}


