package orgclient

import (
	"context"
	"time"

	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
)

// VerifyMembership resolves whether userID holds an active membership in
// orgID and, if so, the bare org role string ("OWNER"/"ADMIN"/"MEMBER"/
// "VIEWER"; "" for a non-member). Used by each consuming BFF's
// ResolveOrgRole middleware to forward the caller's org role as x-org-role
// on its own access-management/curation routes. The inbound ctx is used
// as-is for outgoing metadata (carrying the CALLER's forwarded bearer
// token, never a service-account credential) but bounded with a short
// deadline so a stalled org-svc cannot pin the request goroutine.
//
// azp subtlety (preserved from the original range-bff/internal/orgclient):
// org-svc's VerifyMembership azp allowlist is keyed on the azp claim of the
// forwarded token, not on which BFF happens to be making the gRPC call —
// e.g. range-bff forwards a token whose azp is shell-bff (the browser
// authenticates via shell-bff's Keycloak public client), and that is what
// org-svc checks against its allowlist. Every consuming BFF MUST keep
// forwarding the caller's own bearer token unchanged; swapping in a
// service-account credential here would defeat that allowlist.
func (c *Client) VerifyMembership(ctx context.Context, userID, orgID string) (bool, string, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	resp, err := c.tenant.VerifyMembership(ctx, &tenantv1.VerifyMembershipRequest{
		UserId: userID,
		OrgId:  orgID,
	})
	if err != nil {
		return false, "", err
	}
	return resp.GetIsMember(), resp.GetMembershipRole(), nil
}

// ListMembershipsByTenant returns the membership roster of the caller's own
// org via org-svc TenantService.ListMembershipsByTenant. There is no
// additional RBAC/ownership gate on this RPC beyond org-svc's own RLS
// scoping by tenant — any authenticated org member may read their org's
// roster. The inbound ctx MUST carry the caller's bearer token + x-tenant-id
// in outgoing gRPC metadata — org-svc's RLS scopes results by
// app.current_org_id set from that header.
func (c *Client) ListMembershipsByTenant(ctx context.Context, tenantID string) ([]*tenantv1.Membership, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	resp, err := c.tenant.ListMembershipsByTenant(ctx, &tenantv1.ListMembershipsByTenantRequest{
		TenantId: tenantID,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetMemberships(), nil
}


